try {
  return await this.client.$transaction(async (tx) => {
    // ... existing transaction body ...
  })
} catch (err) {
  // Two concurrent requests with the same proposalKey both passed the
  // read guard above and raced to INSERT; the unique index let exactly
  // one through. Return the winner's row rather than surfacing a 500.
  if (
    rest.proposalKey &&
    err instanceof Prisma.PrismaClientKnownRequestError &&
    err.code === 'P2002'
  ) {
    const winner = await this.findByProposalKeyAndOrganizationSlug(
      rest.proposalKey,
      organizationSlug,
    )
    if (winner) return winner
  }
  throw err
}

